          ["string","'building'"],["text",", fill: "],["keyword","true"],["text",", xy })),\n};\n\n"],
          ["comment","/** A zone the vehicle keeps clear ahead of it, dashed, for a view's `foreground`. */"],["text","\n"],
          ["keyword","export"],["text"," "],["keyword","const"],["text"," SAFETY_ZONE: NeatBevLayer = {\n  lines: [\n    {\n      label: "],
          ["string","'safety zone'"],["text",",\n      closed: "],
          ["keyword","true"],["text",",\n      style: "],
          ["string","'dashed'"],["text",",\n      xy: block(-1.5, 7, -1.6, 1.6),\n    },\n  ],\n};\n"]
